sketches.source:
setcpm(60/4)
song("intro@4 rain@16 downpour@8 rain'@16 outro@4", "once")
tempomap("0:15 44:15 48:12")   // steady, then easing over the last four bars

// Rain on the leaves above you, heavier in the downpour
rain: s("rain").slow(4).intensity(bysec("intro:.3 downpour:.8 outro:.3 *:.5"))
  .elevation(40).distance(3).gain(.26)

// A fine mist: unrelated pink noise in each ear, wide and all around
mist: s("pink").slow(8).icorr(.1).hpf(3000).lpf(8000).gain(.025).exceptSections("intro")

// Drops falling from the canopy at random points around your head
drips: s("drip*8?0.5").azimuth(rand.range(-180, 180)).elevation(rand.range(0, 60))
  .distance(rand.range(1, 4)).seed("canopy").gain(.18)

// A 2 Hz binaural drone: each ear is detuned by 1 Hz, below the 3-30 Hz warning range
// It rises and falls once over the whole piece
drone: note("<d2 d2 bb1 c2>").slow(2).s("sine").binaural(2)
  .attack(3).sustain(1).release(4).gain(env("0 .24@6 0", "song"))

// A soft pad: Dm, Bb, Gm, A; in the second rain it opens up
pad: note("<[d3,a3,f4] [bb2,f3,d4] [g2,d3,bb3] [a2,e3,c#4]>").slow(2)
  .s("sawtooth").unison(3).detune(.2).lpf(900).variant(x => x.lpf(1600))
  .attack(2).release(3).room(.7).gain(.12).sections("rain downpour")

setcpm(60/4)
// Two passes: the first ends with a guide phrase, the second with the tune alone
song("clearing@4 (spring@8 1.guide@4 2.alone@4)*2 clearing'@4", "once")
tempomap("0:15 28:15 32:12")

// The spring bubbling up nearby, a breeze and a bird in the trees
spring: s("stream").slow(4).azimuth(-30).distance(2).gain(.2)
breeze: s("wind").slow(8).intensity(.15).gain(.06)
bird: s("bird").slow(4).azimuth(60).elevation(20).distance(6).gain(.16)

// Splashes: the same noise in both ears, but one ear is phase-shifted in a narrow band
// Neither ear alone hears a tone; together they hear a faint tune in the water
tune: s("[~ white]*4").dichotic("<[392 440 494 587] [523 494 440 392] [330 392 440 494] [440 392 330 294]>")
  .dichoticq(30).attack(.01).sustain(1).release(.08).gain(.12).exceptSections("clearing")

// A quiet guide: the first phrase on a sine, lined up with the tune
hint: note("<[~ g4 ~ a4 ~ b4 ~ d5] ~ ~ ~>").s("sine")
  .decay(.3).sustain(.2).release(.2).gain(.08).sections("guide")

// A soft pad holding the key: G, C, Em, D; it drops out to leave the tune alone
pad: note("<[g2,d3,b3] [c3,g3,e4] [e2,b2,g3] [d3,a3,f#4]>")
  .s("triangle").timbre("soft").attack(1).sustain(.6).release(2)
  .lpf(1000).room(.6).gain(.14).exceptSections("alone")
